     6	public enum ReservationStatus {
     7	    PENDING,
     8	    CONFIRMED,
     9	    CHECKED_IN,
    10	    CHECKED_OUT,
    11	    CANCELLED;
    12	
    13	    /** Todas as mudanças de situação permitidas, num lugar só. */
    14	    public boolean canMoveTo(ReservationStatus next) {
    15	        return switch (this) {
    16	            case PENDING -> next == CONFIRMED || next == CANCELLED;
    17	            case CONFIRMED -> next == CHECKED_IN || next == CANCELLED;
    18	            case CHECKED_IN -> next == CHECKED_OUT;
    19	            case CHECKED_OUT, CANCELLED -> false;
    20	        };
    21	    }
    22	
    23	    /** Reserva paga e ainda válida: confirmada, com check-in ou com check-out. */
    24	    public boolean isPaid() {
    25	        return this == CONFIRMED || this == CHECKED_IN || this == CHECKED_OUT;
    26	    }
