     1	package br.com.marealta.pousada.messaging;
     2	
     3	import java.util.List;
     4	
     5	/** Passa cada mensagem, na ordem, pelas regras que valem para o modo atual. */
     6	public final class MessagePipeline {
     7	    private final List<MessagePolicy> policies;
     8	
     9	    public MessagePipeline(List<Rule> rules, boolean testMode) {
    10	        this.policies = rules.stream()
    11	                .filter(rule -> rule.scope().appliesTo(testMode))
    12	                .map(Rule::policy)
    13	                .toList();
    14	    }
    15	
    16	    public List<Message> process(Message draft) {
    17	        List<Message> current = List.of(draft);
    18	        for (MessagePolicy policy : policies) {
    19	            current = current.stream().flatMap(message -> policy.apply(message).stream()).toList();
    20	        }
    21	        return current;
    22	    }
    23	}
