     1	package br.com.marealta.pousada.messaging;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	import java.util.Map;
     6	import java.util.function.Supplier;
     7	
     8	/**
     9	 * As regras que existem e a combinação usada por cada instalação.
    10	 * Uma regra nova entra com uma classe e uma linha em {@link #AVAILABLE}.
    11	 */
    12	public final class MessageRules {
    13	    public static final String ARCHIVE_ADDRESS = "arquivo@pousadamarealta.com.br";
    14	    public static final String TEST_ADDRESS = "testes@pousadamarealta.com.br";
    15	
    16	    private static final Map<String, Supplier<MessagePolicy>> AVAILABLE = Map.of(
    17	            "valid-address", ValidAddressPolicy::new,
    18	            "test-redirect", () -> new TestRedirectPolicy(TEST_ADDRESS),
    19	            "archive-copy", () -> new ArchiveCopyPolicy(ARCHIVE_ADDRESS));
    20	
    21	    /** A ordem importa: valida antes de redirecionar, e copia por último. */
    22	    public static final String DEFAULT = "valid-address,test-redirect:test,archive-copy:live";
    23	
    24	    private MessageRules() {
    25	    }
    26	
    27	    /** Lê uma lista como "valid-address,test-redirect:test,archive-copy:live" (escopos: always, test, live). */
    28	    public static List<Rule> parse(String spec) {
    29	        List<Rule> rules = new ArrayList<>();
    30	        for (String item : spec.split(",")) {
    31	            String[] parts = item.trim().split(":");
    32	            Supplier<MessagePolicy> policy = AVAILABLE.get(parts[0]);
