     6	public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
     7	
     8	    public static Quote of(RoomType type, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
     9	        BigDecimal subtotal = Money.ZERO;
    10	        int nights = 0;
    11	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    12	            BigDecimal nightPrice = Money.round(type.nightlyRate().multiply(Season.multiplierOf(night)));
    13	            subtotal = Money.round(subtotal.add(nightPrice));
    14	            nights++;
    15	        }
    16	        BigDecimal discount = plan.discountOn(subtotal);
    17	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    18	    }
    19	}
