    17	        if (address == null) {
    18	            return false;
    19	        }
    20	        int at = address.indexOf('@');
    21	        if (at <= 0 || at != address.lastIndexOf('@')) {
    22	            return false;
    23	        }
    24	        String domain = address.substring(at + 1);
    25	        return domain.length() > 2 && domain.substring(1, domain.length() - 1).contains(".");
    26	    }
    27	}
