    10	public final class Database implements AutoCloseable {
    11	    private static final int CONNECTION_ATTEMPTS = 30;
    12	
    13	    private final HikariDataSource dataSource;
    14	
    15	    public Database(String url, String user, String password) {
    16	        HikariConfig config = new HikariConfig();
    17	        config.setJdbcUrl(url);
    18	        config.setUsername(user);
    19	        config.setPassword(password);
    20	        config.setMaximumPoolSize(10);
    21	        config.setInitializationFailTimeout(-1);
    22	        this.dataSource = new HikariDataSource(config);
    23	        createSchema();
    24	    }
    25	
    26	    /** Roda tudo numa transação: ou grava tudo, ou nada. */
    27	    public <T> T transaction(Function<Tx, T> work) {
    28	        try (Connection connection = dataSource.getConnection()) {
    29	            connection.setAutoCommit(false);
    30	            try {
    31	                T result = work.apply(new Tx(connection));
    32	                connection.commit();
    33	                return result;
    34	            } catch (RuntimeException e) {
    35	                connection.rollback();
    36	                throw e;
    37	            }
    38	        } catch (SQLException e) {
