    26	
    27	    public Reservation create(NewReservation request) {
    28	        return database.transaction(tx -> {
    29	            var room = Rooms.find(request.roomNumber()).orElseThrow(() ->
    30	                    new DomainException(ErrorCode.ROOM_NOT_FOUND, "Quarto " + request.roomNumber() + " não existe"));
    31	            Reservation reservation = Reservation.open(request, room);
    32	            tx.reservations().lockRoom(room.number());
    33	            if (tx.reservations().isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    34	                throw new DomainException(ErrorCode.ROOM_UNAVAILABLE, "O quarto já está reservado em alguma das noites");
    35	            }
    36	            return tx.reservations().insert(reservation);
    37	        });
    38	    }
    39	
    40	    public Reservation get(long id) {
    41	        return database.transaction(tx -> tx.reservations().find(id).orElseThrow(() -> notFound(id)));
    42	    }
    43	
    44	    public Reservation confirm(long id) {
    45	        return change(id, Reservation::confirm, (tx, reservation) ->
    46	                tx.messages().insertAll(pipeline.process(ReservationEmails.confirmation(reservation))));
    47	    }
    48	
    49	    public Reservation cancel(long id) {
    50	        return change(id, Reservation::cancel, (tx, reservation) -> { });
    51	    }
    52	
    53	    public Reservation checkIn(long id) {
    54	        return change(id, Reservation::startStay, (tx, reservation) -> { });
    55	    }
    56	
    57	    public Receipt checkOut(long id) {
    58	        return Receipt.of(change(id, Reservation::endStay, (tx, reservation) -> { }));
    59	    }
    60	
    61	    public Receipt document(long id) {
    62	        return get(id).receipt();
    63	    }
