    69	    /** Sequência comum às operações: trava, aplica a mudança, grava e executa o que decorre dela. */
    70	    private Reservation change(long id, Consumer<Reservation> operation, BiConsumer<Tx, Reservation> afterwards) {
    71	        return database.transaction(tx -> {
    72	            Reservation reservation = tx.reservations().findForUpdate(id).orElseThrow(() -> notFound(id));
    73	            operation.accept(reservation);
    74	            tx.reservations().update(reservation);
    75	            afterwards.accept(tx, reservation);
    76	            return reservation;
    77	        });
    78	    }
