  9	import org.junit.jupiter.api.AfterEach;
 10	import org.junit.jupiter.api.Assumptions;
 11	import org.junit.jupiter.api.BeforeAll;
 12	import org.junit.jupiter.api.Test;
 13	
 14	class ApiTest {
 15	    private static final ObjectMapper JSON = new ObjectMapper()
 16	            .enable(com.fasterxml.jackson.databind.DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS)
 17	            .setNodeFactory(com.fasterxml.jackson.databind.node.JsonNodeFactory.withExactBigDecimals(true));
 18	    private TestSystem system;
 19	
 20	    @BeforeAll
 21	    static void requireDatabase() {
 22	        Assumptions.assumeTrue(TestSystem.databaseAvailable(), "PostgreSQL indisponível");
 23	    }
 24	
 25	    @AfterEach
 26	    void stop() throws Exception {
 27	        if (system != null) {
 28	            system.close();
 29	        }
 30	    }
 31	
 32	    private static String body(int room, String email, String in, String out, int guests, String plan) {
 33	        return """
 34	                {"roomNumber":%d,"guestName":"Carla Dias","guestEmail":"%s","guestCpf":"111.222.333-44",
 35	                 "checkIn":"%s","checkOut":"%s","guests":%d,"ratePlan":"%s"}""".formatted(room, email, in, out, guests, plan);
 36	    }
 37	
 38	    private JsonNode reserve(int room, String email, String in, String out, int guests, String plan) throws Exception {
 39	        var response = system.post("/reservations", body(room, email, in, out, guests, plan));
 40	        assertEquals(201, response.status(), response.body());
 41	        return JSON.readTree(response.body());
 42	    }
 43	
 44	    private void assertError(TestSystem.Response response, int status, String code) throws Exception {
 45	        assertEquals(status, response.status(), response.body());
 46	        assertEquals(code, JSON.readTree(response.body()).get("error").asText());
 47	    }
 48	
 49	    @Test
 50	    void reservationLifecycleAndConfirmationEmail() throws Exception {
 51	        system = TestSystem.start(false, MessageRules.DEFAULT);
 52	        JsonNode created = reserve(201, "carla@exemplo.com", "2027-03-10", "2027-03-12", 2, "STANDARD");
 53	        assertEquals(1, created.get("id").asInt());
 54	        assertEquals("PENDING", created.get("status").asText());
 55	        assertEquals("779.80", created.get("subtotal").decimalValue().toPlainString());
 56	        assertEquals("0.00", created.get("amountPaid").decimalValue().toPlainString());
 57	        assertTrue(created.get("refund").isNull());
 58	        assertError(system.get("/reservations/1/document"), 409, "OPERATION_NOT_ALLOWED");
 59	
 60	        JsonNode confirmed = JSON.readTree(system.post("/reservations/1/confirmation", "").body());
 61	        assertEquals("CONFIRMED", confirmed.get("status").asText());
 62	        assertEquals("779.80", confirmed.get("amountPaid").decimalValue().toPlainString());
 63	        assertError(system.post("/reservations/1/confirmation", ""), 409, "OPERATION_NOT_ALLOWED");
 64	
 65	        JsonNode messages = JSON.readTree(system.get("/messages").body());
 66	        assertEquals(2, messages.size());
 67	        String receipt = """
 68	                Comprovante de reserva nº 1
 69	                Hóspede: Carla Dias (CPF 111.222.333-44)
 70	                Quarto: 201 (DELUXE)
 71	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
 72	                Diárias: R$ 779,80
 73	                Total: R$ 779,80""";
 74	        String expectedBody = "Olá, Carla Dias!\n\nSua reserva na Pousada Maré Alta está confirmada. "
 75	                + "Estes são os dados dela:\n\n" + receipt
 76	                + "\n\nA entrada é a partir das 14h, e a saída, até as 12h.\nAté breve!";
 77	        JsonNode first = messages.get(0);
 78	        assertEquals("EMAIL", first.get("channel").asText());
 79	        assertEquals("carla@exemplo.com", first.get("to").asText());
 80	        assertEquals("Reserva confirmada - Pousada Maré Alta", first.get("subject").asText());
 81	        assertEquals(expectedBody, first.get("body").asText());
 82	        assertEquals("SENT", first.get("status").asText());
 83	        JsonNode copy = messages.get(1);
 84	        assertEquals("arquivo@pousadamarealta.com.br", copy.get("to").asText());
 85	        assertEquals("[Cópia] Reserva confirmada - Pousada Maré Alta", copy.get("subject").asText());
 86	        assertEquals(expectedBody, copy.get("body").asText());
 87	
 88	        JsonNode checkedIn = JSON.readTree(system.post("/reservations/1/check-in", "").body());
 89	        assertEquals("CHECKED_IN", checkedIn.get("status").asText());
 90	        assertError(system.post("/reservations/1/cancellation", ""), 409, "OPERATION_NOT_ALLOWED");
 91	        JsonNode out = JSON.readTree(system.post("/reservations/1/check-out", "").body());
