314	import java.sql.DriverManager;
315	import java.sql.SQLException;
316	import java.sql.Statement;
317	import java.util.UUID;
318	
319	/** Sobe o sistema inteiro num schema próprio do PostgreSQL, que some no fim. */
320	final class TestSystem implements AutoCloseable {
321	    private static final String URL = System.getenv("DB_URL");
322	    private static final String USER = System.getenv("DB_USER");
323	    private static final String PASSWORD = System.getenv("DB_PASSWORD");
324	
325	    private final String schema;
326	    private final Javalin app;
327	    private final String baseUrl;
328	    private final HttpClient client = HttpClient.newHttpClient();
329	
330	    private TestSystem(String schema, Config config) {
331	        this.schema = schema;
332	        this.app = Main.start(config).start(0);
333	        this.baseUrl = "http://localhost:" + app.port();
334	    }
335	
336	    static boolean databaseAvailable() {
337	        if (URL == null) {
338	            return false;
339	        }
340	        try (Connection ignored = DriverManager.getConnection(URL, USER, PASSWORD)) {
341	            return true;
342	        } catch (SQLException e) {
343	            return false;
344	        }
345	    }
346	
347	    static TestSystem start(boolean testMode, String messageRules) throws SQLException {
348	        String schema = "t_" + UUID.randomUUID().toString().replace("-", "");
349	        execute("CREATE SCHEMA " + schema);
350	        String separator = URL.contains("?") ? "&" : "?";
351	        Config config = new Config(0, URL + separator + "currentSchema=" + schema, USER, PASSWORD, testMode, messageRules);
352	        return new TestSystem(schema, config);
353	    }
354	
355	    private static void execute(String sql) throws SQLException {
356	        try (Connection c = DriverManager.getConnection(URL, USER, PASSWORD); Statement s = c.createStatement()) {
357	            s.execute(sql);
358	        }
359	    }
360	
361	    record Response(int status, String contentType, String body) {
362	    }
363	
364	    Response get(String path) throws Exception {
365	        return send(HttpRequest.newBuilder(URI.create(baseUrl + path)).GET().build());
366	    }
367	
368	    Response post(String path, String body) throws Exception {
369	        return send(HttpRequest.newBuilder(URI.create(baseUrl + path))
370	                .POST(HttpRequest.BodyPublishers.ofString(body)).build());
371	    }
372	
373	    private Response send(HttpRequest request) throws Exception {
374	        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
375	        return new Response(response.statusCode(), response.headers().firstValue("content-type").orElse(""), response.body());
376	    }
377	
378	    @Override
379	    public void close() throws Exception {
380	        app.stop();
381	        execute("DROP SCHEMA IF EXISTS " + schema + " CASCADE");
382	    }
383	}

